//我在(0,0)点放置了一个半径为.2的圆,并计算了空间点p到圆表面的有向距离
//所谓有向(signed)就是指,当这个点位于圆内部时这个距离会输出为负值
float SDF(vec2 p){
    float s = length( p - vec2(0.0))-0.2;
    return s;
}

void mainImage( out vec4 O, in vec2 C )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (C - 0.5 *iResolution.xy) /iResolution.y;

    //O.xyz = vec3(step(0.0, SDF(uv)));
    //
    float seg = floor(SDF(uv)*20.0);
    O.xyz = mix(vec3(0.7,0.5,0.3),vec3(0.3,0.4,0.4),seg/6.0);

}
